        "title": "Launching from the Custom Golden AMI",
        "command": "TEST_NODE_ID=$(aws ec2 run-instances \\\n  --region \"${AWS_REGION}\" \\\n  --image-id \"${CUSTOM_AMI_ID}\" \\\n  --instance-type \"t3.micro\" \\\n  --subnet-id \"${SUBNET_ID}\" \\\n  --tag-specifications \"ResourceType=instance,Tags=[{Key=Project,Value=ec2-master-labs},{Key=Name,Value=test-ami-instance}]\" \\\n  --query \"Instances[0].InstanceId\" --output text)",
