        "title": "Creating the EFS Security Group and Opening NFS Port 2049",
        "command": "EFS_SG_ID=$(aws ec2 create-security-group \\\n  --group-name \"efs-mount-target-sg\" \\\n  --description \"Allow NFS traffic from EC2 instances\" \\\n  --vpc-id \"${VPC_ID}\" \\\n  --query \"GroupId\" --output text)\n\naws ec2 authorize-security-group-ingress \\\n  --group-id \"${EFS_SG_ID}\" \\\n  --protocol tcp \\\n  --port 2049 \\\n  --cidr \"${VPC_CIDR}\"",
