        "fullCommand": "# \u2554\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# \u2551 \ud83d\udccc Command 2: Bridging the IAM Role into an EC2 Instance Profile\n# \u2560\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# \u2551 \ud83c\udfaf PURPOSE & SCOPE:\n# \u2551    What is an Instance Profile? In AWS Identity and Access Management, an **IAM Role** is a pure policy construct.\n# \u2551    However, the EC2 service requires a physical container called an **IAM Instance Profile** to pass that role to\n# \u2551    the hypervisor. When using the AWS Management Console, AWS automatically creates an instance profile with the\n# \u2551    exact same name as the IAM role behind the scenes. When using the AWS CLI or Terraform, this two-step binding\n# \u2551    must be performed explicitly.\n# \u2551\n# \u2551 \ud83d\udd0d KEY PARAMETERS & SYNTAX:\n# \u2551    \u2022 `add-role-to-instance-profile` Places the role inside the profile container. Each instance profile can contain\n# \u2551         at most one IAM role.\n# \u2551\n# \u2551 \u2699\ufe0f PRODUCTION IMPACT & ARCHITECTURE:\n# \u2551    Attempting to attach an IAM role directly to an EC2 instance without creating an instance profile first will\n# \u2551    throw an `InvalidParameterValue` error. Automating this pairing is standard across Terraform\n# \u2551    (`aws_iam_instance_profile`) and CloudFormation (`AWS::IAM::InstanceProfile`).\n# \u255a\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# 1. Create the Instance Profile container\naws iam create-instance-profile \\\n  --instance-profile-name \"ec2-labs-s3-reader-profile\"\n\n# 2. Add the IAM Role into the Instance Profile container\naws iam add-role-to-instance-profile \\\n  --instance-profile-name \"ec2-labs-s3-reader-profile\" \\\n  --role-name \"ec2-labs-s3-reader-role\"",
