        "command": "export AWS_REGION=$(aws configure get region || echo \"us-east-1\")\nexport VPC_ID=$(aws ec2 describe-vpcs --filters \"Name=isDefault,Values=true\" --query \"Vpcs[0].VpcId\" --output text)\nSUBNET_1=$(aws ec2 describe-subnets --filters \"Name=vpc-id,Values=${VPC_ID}\" --query \"Subnets[0].SubnetId\" --output text)\nSUBNET_2=$(aws ec2 describe-subnets --filters \"Name=vpc-id,Values=${VPC_ID}\" --query \"Subnets[1].SubnetId\" --output text)",
        "fullCommand": "# \u2554\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# \u2551 \ud83d\udccc Command 1: Discovering Network Subnets and AWS Region\n# \u2560\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# \u2551 \ud83c\udfaf PURPOSE & SCOPE:\n# \u2551    `export AWS_REGION=...`: Queries the default region from local AWS CLI configuration profile (`~/.aws/config`).\n# \u2551    If not set, falls back to `us-east-1`.\n# \u2551\n# \u2551 \ud83d\udd0d KEY PARAMETERS & SYNTAX:\n# \u2551    \u2022 `aws ec2 describe-vpcs --filters \"Name=isDefault,Values=true\"`: Filters VPCs to discover the default AWS VPC\n# \u2551         created in the region.\n# \u2551    \u2022 `--query \"Vpcs[0].VpcId\" --output text`: Extracts the raw VPC identifier string (e.g.,\n# \u2551         `vpc-0123456789abcdef0`).\n# \u2551    \u2022 `aws ec2 describe-subnets --filters \"Name=vpc-id,Values=${VPC_ID}\"`: Lists all subnets provisioned inside the\n# \u2551         target VPC.\n# \u2551    \u2022 `--query \"Subnets[0].SubnetId\"` and `--query \"Subnets[1].SubnetId\"`: Pulls two distinct subnet IDs residing in\n# \u2551         different Availability Zones within the default VPC.\n# \u2551\n# \u2551 \u2699\ufe0f PRODUCTION IMPACT & ARCHITECTURE:\n# \u2551    An Auto Scaling Group achieves high availability only when distributed across multiple Availability Zones.\n# \u2551    Passing multiple subnet IDs ensures that EC2 instances launched by the ASG are balanced across physical AZs,\n# \u2551    mitigating localized infrastructure outages.\n# \u255a\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nexport AWS_REGION=$(aws configure get region || echo \"us-east-1\")\nexport VPC_ID=$(aws ec2 describe-vpcs --filters \"Name=isDefault,Values=true\" --query \"Vpcs[0].VpcId\" --output text)\nSUBNET_1=$(aws ec2 describe-subnets --filters \"Name=vpc-id,Values=${VPC_ID}\" --query \"Subnets[0].SubnetId\" --output text)\nSUBNET_2=$(aws ec2 describe-subnets --filters \"Name=vpc-id,Values=${VPC_ID}\" --query \"Subnets[1].SubnetId\" --output text)",
