        "fullCommand": "# \u2554\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# \u2551 \ud83d\udccc Command 5: Command 7: Signaling Completion of the Lifecycle Action\n# \u2560\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# \u2551 \ud83c\udfaf PURPOSE & SCOPE:\n# \u2551    `aws autoscaling complete-lifecycle-action`: Signals to the Auto Scaling engine that custom drain procedures\n# \u2551    have finished.\n# \u2551\n# \u2551 \ud83d\udd0d KEY PARAMETERS & SYNTAX:\n# \u2551    \u2022 `--lifecycle-hook-name \"graceful-drain-hook\"`: Identifies the active hook.\n# \u2551    \u2022 `--auto-scaling-group-name \"asg-hook-demo\"`: Parent ASG name.\n# \u2551    \u2022 `--lifecycle-action-result \"CONTINUE\"`: Informs ASG that the drain succeeded and it can now proceed with\n# \u2551         terminating the instance (`Terminating:Proceed`).\n# \u2551    \u2022 `--instance-id \"${INSTANCE_ID}\"`: The instance that has completed its drain tasks.\n# \u2551\n# \u2551 \u2699\ufe0f PRODUCTION IMPACT & ARCHITECTURE:\n# \u2551    Waiting for the full 300-second heartbeat timeout slows down scaling and wastes compute cost. Signaling\n# \u2551    `complete-lifecycle-action` immediately upon drain completion ensures rapid, cost-efficient infrastructure\n# \u2551    cycling without unnecessary idle delays.\n# \u255a\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\naws autoscaling complete-lifecycle-action \\\n  --lifecycle-hook-name \"graceful-drain-hook\" \\\n  --auto-scaling-group-name \"asg-hook-demo\" \\\n  --lifecycle-action-result \"CONTINUE\" \\\n  --instance-id \"${INSTANCE_ID}\"",
