        "shortTitle": "3. Command 5: Auditing In...",
        "title": "Command 5: Auditing Instance Types and Pricing Distribution",
        "command": "aws ec2 describe-instances \\\n  --filters \"Name=tag:aws:autoscaling:groupName,Values=asg-mixed-fleet-demo\" \\\n  --query \"Reservations[*].Instances[*].[InstanceId,InstanceType,InstanceLifecycle||'on-demand',Placement.AvailabilityZone]\" \\\n  --output table",
