        "status": "Step 1: Command 3: Provisioning Clou",
        "statusColor": "bg-blue-500",
        "activePacket": "CLI \u2192 AWS Monitoring & Troubleshooting: Command 3: Provisioning CloudWatch Log Group and Enabling VPC Flow Logs"
